    {{ p.permalink }}
    {{ p.date | date(format="%a, %d %b %Y %H:%M:%S %z") }}
    {%- if p.summary %}{{ p.summary | striptags | truncate(length=300) }}{%- endif %}
    {%- set_global _tx = p.taxonomies | default(value={}) -%}
    {%- for tag in _tx.tags | default(value=[]) %}
    {{ tag }}
    {%- endfor %}

  {%- endif %}
{%- endfor %}
